SELECT 100.0 * SUM(CASE WHEN STRFTIME('%Y', p.CreaionDate) = '2011' AND u.Reputation > 1000 THEN 1 ELSE 0 END) / COUNT(p.Id) AS percentage
FROM posts p
LEFT JOIN users u ON p.OwnerUserId = u.Id;

SELECT 100.0 * SUM(CASE WHEN a.element = 'c' THEN 1 ELSE 0 END) / COUNT(a.atom_id) AS percentage
FROM atom a
WHERE a.molecule_id IN (SELECT molecule_id FROM bond WHERE bond_type = '=');

SELECT School FROM (
SELECT s.School, ROW_NUMBER() OVER (PARTITION BY s.County ORDER BY sat.AvgScrRead DESC) AS rn
FROM schools s
JOIN satscores sat ON s.CDSCode = sat.cds
WHERE s.Virtual = 'F'
) WHERE rn <= 5;
